/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
path = Path('src/dashboard.tsx')
text = path.read_text()
old = '''      <DashKitDnDWrapper>
        <DashKit
          config={config}
          editMode={editMode}
          itemsStateAndParams={itemsStateAndParams}
          onChange={handleChange}
          onDrop={(dropProps) => {
            const type = dropProps.dragProps.type;
            setConfig((currentConfig) => {
              const nextConfig = DashKit.setItem({
                item: { data: {}, type, namespace: 'dashboard' },
                config: currentConfig,
              });
              return nextConfig;
            });
            dropProps.commit();
          }}
        />
        <ActionPanel items={paletteItems} />
      </DashKitDnDWrapper>'''
new = '''      <DashKitDnDWrapper>
        <Flex direction=\"row\" alignItems=\"flex-start\" gap=\"4\">
          <DashKit
            config={config}
            editMode={editMode}
            itemsStateAndParams={itemsStateAndParams}
            onChange={handleChange}
            onDrop={(dropProps) => {
              const type = dropProps.dragProps.type;
              setConfig((currentConfig) => {
                const nextConfig = DashKit.setItem({
                  item: { data: {}, type, namespace: 'dashboard' },
                  config: currentConfig,
                });
                return nextConfig;
              });
              dropProps.commit();
            }}
          />
          <ActionPanel items={paletteItems} />
        </Flex>
      </DashKitDnDWrapper>'''
if old not in text:
    raise SystemExit('target text not found')
path.write_text(text.replace(old, new))
PY
npm run build"

